 "content": "from collections import Counter, deque


def _components(grid, predicate):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen or not predicate(grid[r][c]):
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and predicate(grid[nx][ny]):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            out.append(cells)
    return out


def transform(grid):
    g = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sources = _components(grid, lambda v: v != background and v != 0)
    targets = _components(grid, lambda v: v == 0)
    if not sources or not targets:
        return g
    src = max(sources, key=len)
    dst = max(targets, key=len)
    sr0, sr1 = min(r for r, c in src), max(r for r, c in src)
    sc0, sc1 = min(c for r, c in src), max(c for r, c in src)
    dr0, dr1 = min(r for r, c in dst), max(r for r, c in dst)
    dc0, dc1 = min(c for r, c in dst), max(c for r, c in dst)
    sh, sw = sr1 - sr0 + 1, sc1 - sc0 + 1
    dh, dw = dr1 - dr0 + 1, dc1 - dc0 + 1
    if (sh, sw) != (dh, dw):
        return g
    for r in range(sh):
        for c in range(sw):
            g[dr0 + r][dc0 + c] = grid[sr0 + r][sc1 - c]
    return g


